INSERT INTO `whatsapp_messages` VALUES (1,'unknow_keyword',NULL,'Unknow Keyword','unknow keyword','Mohon maaf, keywoard yang anda masukkan salah\n\nKeyword yang tersedia:\n%keywords%','Pesan yang dikirim saat pesan yang diterima tidak ada dalam keyword.',1,0,'2024-11-27 12:31:43','2024-11-27 12:31:43',NULL),(2,'payment',NULL,'Pembayaran Lunas','payment','===============================\r\n           *KWITANSI PEMBAYARAN*\r\n          Receipt # : %billing_number%\r\n===============================\r\n\r\nPelanggan yang terhormat, Berikut kami sampaikan detail pembayaran anda:\r\n\r\n? *Nama       :* _Bpk/Ibu %name%_\r\n? *Cust - ID  :* _%customer_id%_\r\n? *Alamat     :* _%address%_\r\n? *Paket        :* _%paket%_\r\n? *Periode    :* _%periode%_\r\n? *Nominal   :* *_%bill%_*\r\n\r\n*Teller      :* _%teller%_\r\n*Tanggal :* _%payment_time%_\r\n*Metode pembayaran :* _%payment_methode%_\r\n\r\n===============================\r\nTerima kasih telah mempercayakan kebutuhan internetnya kepada kami.\r\nKami berkomitmen untuk selalu memberikan yang terbaik.\r\nMohon maaf jika ada salah penulisan nama, Anda dapat menghubungi kami untuk pembetulan.\r\n===============================\r\n            *_Shanum Network Fiber_*\r\n===============================','Pesan yang dikirim saat pelanggan melakukan pembayaran.',1,0,'2024-11-27 12:31:43','2024-12-01 11:02:28',NULL),(3,'unknow_customer',NULL,'Non Customer','unknow customer','Mohon maaf, anda belum terdaftar sebagai customer kami.\nSilahkan menghubungi 086726455588 untuk proses registrasi.','Pesan yang dikirim bukan customer.',1,0,'2024-11-27 12:31:43','2024-11-27 12:31:43',NULL),(4,'unpayment',NULL,'Unpayment','unpayment','Yth. Bpk/Ibu %name%,\r\n%address%\r\nCustomer ID : %customer_id%\r\n\r\nMaaf telah terjadi kesalahan system billing kami,\r\n\r\nPembayaran anda:\r\nNomor Tagihan : *%billing_number%*\r\nJumlah : *%bill%*\r\n\r\nTelah dibatalkan.\r\n\r\nTerima kasih telah menggunakan layanan internet kami.\r\n\r\n*Shanum Network Fiber*\r\nJl. Sukamaju No. 49 RT 009/007\r\nCiseureuh, Purwakarta\r\n\r\n*_Pesan ini dikirim otomatis oleh system, anda tidak perlu membalasnya._*','Pesan yang dikirim saat admin melakukan pembatalan pembayaran.',1,0,'2024-11-27 12:31:43','2024-11-28 06:47:00',NULL),(5,'no_paket',NULL,'Customer Dont Have Paket','no paket','Yth. Bp/Ibu %name%,\r\n%address%\r\nCustomer ID: %customer_id%\r\n\r\nSaat ini anda sudah terdaftar di sistem kami, namun belum mempunyai paket.\r\n\r\nJika anda ingin menggunakan layanan kami, silahkan hubungi 0878 1804 0024.\r\n\r\n*Shanum Network Fiber*\r\nJl. Sukamaju No. 49 RT 009/007\r\nCiseureuh, Purwakarta\r\n\r\n*_Pesan ini dikirim otomatis oleh system, anda tidak perlu membalasnya_*','Pesan yang dikirim saat pelanggan tidak memiliki paket internet.',1,0,'2024-11-27 12:31:43','2024-11-27 13:28:08',NULL),(6,'no_bill',NULL,'No Bill','no bill','Yth. Bp/Ibu %name%,\n%address%\nCustomer ID: %customer_id%\n\nSaat ini anda belum memiliki tagihan.\n\nKami mengucapkan terima kasih karena anda tertib administrasi.\nIni sangat berguna untuk kemajuan kami dalam memperbaiki layanan.\n\n*ShaNet Fiber*\nJl. Sukamaju No. 49 RT 009/007\nCiseureuh, Purwakarta\n\n*Pesan ini dikirim otomatis oleh system, anda tidak perlu membalasnya*','Pesan yang dikirim saat pelanggan tidak memiliki tagihan.',1,0,'2024-11-27 12:31:43','2024-11-27 12:31:43',NULL),(7,'reminder_bill',NULL,'Reminder Bill','warning bill','Yth. Bp/Ibu %name%,\r\n%address%\r\nCustomer ID: %customer_id%\r\n\r\n%day% hari lagi adalah batas akhir pembayaran paket %paket-name% internet anda. Saat ini anda memiliki %count-bill% tagihan yang belum dibayar:\r\n\r\n%pakets%\r\n*Jumlah tagihan: %total-bill%*\r\n\r\nLakukan pembayaran sebelum jatuh tempo untuk menghindari isolir otomatis oleh system kami.\r\n\r\nAnda dapat melakukan pembayaran melalui:\r\n%account-bank%\r\nSilahkan konfirmasi ke nomor WhatsApp *0878 1804 0024* setelah melakukan pembayaran dengan mengirimkan bukti transfer.\r\n\r\n_Terima kasih telah menggunakan layanan internet kami._\r\n*Shanum Network Fiber*\r\nJl. Sukamaju No. 49 RT 009/007\r\nCiseureuh, Purwakarta\r\n\r\n*_Pesan ini dikirim otomatis oleh system, anda tidak perlu membalasnya_*','Pesan yang dikirim untuk memberitahukan bahwa tagihan mereka akan jatuh tempo.',1,0,'2024-11-27 12:31:43','2024-12-03 06:52:34',NULL),(8,'deadline_bill',NULL,'Deadline Bill','warning bill','Yth. Bpk/Ibu %name%,\r\n%address%\r\nCustomer ID : %customer_id%\r\n\r\nHari ini adalah batas akhir pembayaran paket %paket-name% internet anda. Saat ini anda memiliki %count-bill% tagihan yang belum dibayar:\r\n\r\n%pakets%\r\n*Jumlah tagihan: %total-bill%*\r\n\r\nSegera lakukan pembayaran sebelum jatuh tempo untuk menghindari isolir otomatis oleh system kami.\r\n\r\nAnda dapat melakukan pembayaran melalui:\r\n%account-bank%\r\nSilahkan konfirmasi ke nomor WhatsApp *0878 1804 0024* setelah melakukan pembayaran dengan mengirimkan bukti transfer.\r\n\r\n_Terima kasih telah menggunakan layanan internet kami._\r\n*Shanum Network Fiber*\r\nJl. Sukamaju No. 49 RT 009/007\r\nCiseureuh, Purwakarta\r\n\r\n*_Pesan ini dikirim otomatis oleh system, anda tidak perlu membalasnya_*','Pesan yang dikirim untuk memberitahukan bahwa tagihan mereka sudah jatuh tempo.',1,0,'2024-11-27 12:31:43','2024-12-03 06:51:13',NULL),(9,'past_due_warning',NULL,'Past Due Warning','warning bill','Yth. Bpk/Ibu %name%,\r\n%address%\r\nCustomer ID : %customer_id%\r\n\r\nKami ingin mengingatkan bahwa Anda memiliki %count-bill% tagihan paket internet yang belum dibayar hingga melewati jatuh tempo.\r\nBerikut adalah rincian tagihan Anda:\r\n\r\n%pakets%\r\n*Jumlah tagihan keseluruhan : %total-bill%*\r\n\r\nPembayaran dapat dilakukan melalui :\r\n%account-bank%\r\n\r\nSilahkan konfirmasi ke nomor WhatsApp *0878 1804 0024* setelah melakukan pembayaran dengan mengirimkan bukti transfer.\r\n\r\n*Shanum Network Fiber*\r\nJl. Sukamaju No. 49 RT 009/007\r\nCiseureuh, Purwakarta\r\n\r\n*_Pesan ini dikirim secara